REG={
'demacia':("Un reino resplandeciente construido sobre la ley, el acero y un profundo miedo a la magia.","Demacia se amuralla con petricita, una piedra blanca que amortigua la magia, y a su gente se le enseña que los magos son peligrosos. Esa norma empieza a resquebrajarse, y algunos de los propios héroes del reino ocultan el mismo poder que este persigue."),
'noxus':("Un imperio que acoge a cualquiera, siempre que demuestre su fuerza.","Noxus se expande por conquista, pero le da igual dónde hayas nacido. Cualquiera puede ascender si es lo bastante fuerte. Tras sus generales, poderes antiguos como la Rosa Negra siguen luchando por ver quién mueve realmente los hilos."),
'piltover':("La Ciudad del Progreso, donde la tecnomagia crea fortunas.","Piltover controla el canal comercial entre dos continentes y se enriqueció con él. La tecnomagia, una mezcla de magia e ingeniería, hizo famosos a sus inventores. Su riqueza se asienta justo encima de Zaun, y ninguna de las dos ciudades lo olvida."),
'zaun':("La ciudad subterránea bajo Piltover, ahogada en quimtecnología y ambición.","Zaun vive en el smog bajo las relucientes torres de Piltover. Los quimiobarones dominan sus calles, la quimtecnología la mantiene con vida y su gente es más dura y extraña por ello. De aquí vienen Jinx, Ekko y Viktor."),
'freljord':("Una tierra helada de tribus rivales y antiguos dioses enterrados.","El Freljord es un norte helado y duro dividido entre tribus en guerra. Tres de ellas están lideradas por mujeres que reclaman el antiguo derecho a gobernar. Bajo el hielo, los Vigilantes esperan a que alguien los despierte."),
'ionia':("Una isla de magia espiritual que aún se recupera de la invasión noxiana.","Jonia es una tierra donde la naturaleza y los espíritus conviven. Noxus la invadió y fue expulsada, pero la guerra dividió a los jonios ante una pregunta difícil: ¿seguir siendo pacíficos o volverse tan despiadados como su enemigo?"),
'shurima':("Un imperio desértico caído cuyo emperador ha vuelto a alzarse.","Shurima gobernó en su día casi todo el mundo gracias a guerreros Ascendidos de poder divino. Después cayó, traicionado desde dentro. Ahora su emperador Azir ha vuelto de la arena, y las viejas rencillas han despertado con él."),
'targon':("Una montaña que llega a las estrellas, donde los dioses eligen anfitriones mortales.","El monte Targon es tan alto que parece tocar el cielo. Quienes alcanzan la cima pueden ser elegidos por un Aspecto, un ser celestial que toma un anfitrión mortal. A sus pies, los adoradores del sol y de la luna llevan siglos en guerra."),
'bilgewater':("Un puerto sin ley de piratas, monstruos y deudas.","Aguasturbias es un puerto sin un gobierno de verdad, solo capitanes, bandas y monstruos marinos. La fortuna y la muerte están siempre a un mal trato de distancia. Su antiguo rey pirata cayó, y ahora una nueva capitana manda en los muelles."),
'shadowisles':("Islas antaño benditas, ahora ahogadas en la Niebla Negra.","Las Islas Benditas eran un lugar de sanación hasta que un rey afligido intentó devolver a la vida a su esposa. La magia se rompió y la Niebla Negra lo engulló todo. Ahora allí los muertos no descansan y siguen extendiéndose."),
'bandle':("El hogar de los yordles, que solo encuentran aquellos a quienes deja entrar.","Ciudad de Bandle existe a medias en el reino espiritual, y su entrada cambia de sitio. Los yordles son pequeños, mágicos e infinitamente curiosos. Recorren el mundo y suelen saber mucho más de lo que aparentan. Recarga la página y su puerta estará en otro lugar."),
'ixtal':("Un reino oculto en la jungla, de magos elementales.","Ixtal se escondió en lo profundo de la jungla durante las Guerras Rúnicas y desde entonces vive apartado del resto del mundo. Sus gobernantes dominan los elementos y sus bosques albergan a algunos de los cazadores más letales."),
'void':("Una nada hambrienta que empuja desde debajo del mundo.","El Vacío no es tanto un lugar como un hambre. Irrumpió en Icathia en tiempos antiguos y desde entonces intenta deshacer Runaterra. Sus criaturas se adaptan, devoran y algunas aprenden a pensar."),
'wanderers':("Dioses, monstruos y viajeros que no responden ante ninguna nación.","No toda leyenda tiene patria. Algunas son más antiguas que las propias naciones, como los Oscuros y los parientes caídos de los Aspectos. Otras caminan entre reinos, guardan las runas que dieron forma al mundo o simplemente cazan donde les place. Aparecen en la historia de todas las regiones, y ninguna pertenece solo a una."),
}
DNA={
'piltover':("Tecnomagia: magia domada por la ciencia y la precisión","Latón pulido, mármol blanco, hextal azul","Simetría, geometría limpia, verticales altas","El art déco neoyorquino, el aspecto que Arcane dio a la ciudad alta"),
'zaun':("Quimtecnología: magia extraída de sustancias químicas, tóxica e inestable","Hierro oxidado, tanques de cristal, tubos de neón, chatarra reutilizada","Asimetría, aire artesanal, adornos orgánicos","El art déco europeo y la industria victoriana, el espejo oscuro de Piltover en Arcane"),
'demacia':("Temida y reprimida por la petricita, la piedra que la amortigua","Petricita blanca, acero pulido, pan de oro, azul real","Alas alzadas, escudos, simetría noble","La caballería de la plena Edad Media y la cantería de catedral"),
'noxus':("Un arma como cualquier otra, de quien sea más fuerte","Hormigón desnudo, hierro negro, tela carmesí, piedra agrietada","Pesado, bajo, con pinchos, brutalista","El estilo brutalista de la cinemática Welcome to Noxus de Riot"),
'freljord':("El Hielo Verdadero y la voluntad de antiguos semidioses","Hielo glaciar, pieles, hueso tallado y pino","Esquirlas, runas, picos dentados","Sagas nórdicas y siberianas"),
'ionia':("Magia espiritual tejida en la tierra y los seres vivos","Madera viva, seda, tinta, flores espirituales","Curvas fluidas, pinceladas, equilibrio","La pintura a tinta de Asia oriental y los jardines de templos"),
'shurima':("La Ascensión, concedida por el Disco Solar","Arenisca, oro batido, lapislázuli, lino","Discos, rayos, pirámides escalonadas","Antiguos imperios del desierto"),
'targon':("Aspectos celestiales que descienden a anfitriones mortales","Luz estelar, granito de montaña, metal celestial","Picos, constelaciones, sol y luna","La astronomía y la peregrinación de montaña"),
'bilgewater':("Dioses marinos, reliquias malditas y pactos con las profundidades","Madera curtida por la sal, cabo alquitranado, latón, tatuajes de tinta","Curvas de casco, garfios, cabos enrollados","Los puertos piratas y la era de la vela"),
'shadowisles':("La Niebla Negra, nacida de la Ruina","Piedra blanca en ruinas, cadenas oxidadas, luz espectral","Arcos góticos, líneas rotas, volutas de niebla","Ruinas góticas e historias de fantasmas"),
'bandle':("Magia yordle salvaje del reino espiritual","Musgo, setas, purpurina, cachivaches prestados","Espirales, formas redondas, nada termina de combinar","Cuentos de hadas y puertas escondidas"),
'ixtal':("Dominio de los elementos: tierra, agua, fuego y viento","Jade, caliza tallada, vegetación de jungla","Pirámides escalonadas, grecas, glifos geométricos","Las ciudades templo mesoamericanas"),
'void':("Deshacer: consume, se adapta y crece","Quitina, cristal violeta, tejido vivo","Púas, ojos, crecimiento fractal","Horror cósmico"),
'wanderers':("Runas Mundiales, armas de los Oscuros y un poder cósmico más antiguo que cualquier nación","Luz estelar, piedra tallada con runas, bronce antiguo","Círculos, órbitas, glifos rúnicos","Mitos y folclore que cruzan todas las fronteras"),
}
